/bin/zsh -lc "cat > crates/vb_runtime/src/shard/tests/test_fixtures.rs << 'EOF'
//"'! Shared test fixture helpers for action contracts and capability grants.
//!
//! These helpers replace the cfg(test) fabrication that previously lived
//! in the production shard lifecycle code. Tests that submit workflows
//! containing Do actions must explicitly provide the necessary contracts
//! and grants using these helpers.

use vb_core::action::{
    ActionContract, ActionName, Idempotency, RetrySafety, SideEffect,
};
use vb_core::capability::{Capability, CapabilitySet};
use vb_core::ids::ActionId;

/// Create an action contract for a given action ID with default values.
///
/// The contract has no required capabilities by default. Use
/// `contract_with_capability` for contracts that require specific capabilities.
pub fn action_contract_for(action: ActionId) -> ActionContract {
    ActionContract {
        id: action,
        name: ActionName::new("test-action").expect("action name is valid"),
        input_slot_count: 1,
        output_slot_count: 1,
        max_input_bytes: 1024,
        max_output_bytes: 1024,
        timeout_ms: 5000,
        idempotency: Idempotency::DeterministicPure,
        side_effect: SideEffect::None,
        retry_safety: RetrySafety::Safe,
        required_capabilities: Box::new([]),
    }
}

/// Create an action contract that requires a specific capability.
pub fn contract_with_capability(
    action: ActionId,
    required: Capability,
) -> ActionContract {
    ActionContract {
        id: action,
        name: ActionName::new("test-action").expect("action name is valid"),
        input_slot_count: 1,
        output_slot_count: 1,
        max_input_bytes: 1024,
        max_output_bytes: 1024,
        timeout_ms: 5000,
        idempotency: Idempotency::DeterministicPure,
        side_effect: SideEffect::None,
        retry_safety: RetrySafety::Safe,
        required_capabilities: Box::new([required]),
    }
}

/// Create a capability set that grants a capability for a specific action.
pub fn capability_grant_for(
    name: &str,
    action: ActionId,
) -> CapabilitySet {
    CapabilitySet::from_grants(Box::new([Capability::new(name.into(), action)]))
}

/// Create action contracts for all action IDs from 0 through the given maximum.
///
/// This is useful for tests that reference multiple actions by ID.
pub fn contracts_through(max_action: ActionId) -> Box<[ActionContract]> {
    let target = u16::from(max_action.get());
    let mut contracts = Vec::with_capacity(usize::from(target) + 1);
    let mut id = 0u16;
    loop {
        let current = ActionId::new(id);
        contracts.push(action_contract_for(current));
        if id == target {
            break;
        }
        id = id.saturating_add(1);
    }
    contracts.into_boxed_slice()
}

/// Create a capability set that grants the default contract capability for the given action.
///
/// The capability name is `__contract_required__`, matching the convention
/// used by `execute_do_without_contract` for fail-closed behavior.
pub fn default_contract_capability_for(action: ActionId) -> CapabilitySet {
    capability_grant_for("__contract_required__", action)
}
EOF'

