#[allow(clippy::too_many_arguments)]
pub(super) fn dispatch_action_and_signal(
    plan: &CompiledWorkflow,
    run: &mut RunFrame,
    store: &mut ValueStore,
    node: &CompiledNode,
    contracts: &[ActionContract],
    retry_policy: RetryPolicy,
    granted: &CapabilitySet,
) -> RuntimeEngineResult<RuntimeSignal> {
    match &node.kind {
        CompiledNodeKind::WaitUntil { .. }
        | CompiledNodeKind::WaitEvent { .. }
        | CompiledNodeKind::Ask { .. }
        | CompiledNodeKind::AskResume { .. } => dispatch_signal(run, node),
        CompiledNodeKind::Do { .. }
        | CompiledNodeKind::RetryCheck { .. }
        | CompiledNodeKind::ErrorHandler { .. } => {
            dispatch_action(run, node, contracts, retry_policy, granted)
        }
        _ => handle_core_step_once(plan, run, store),
    }
}

fn dispatch_signal(run: &mut RunFrame, node: &CompiledNode) -> RuntimeEngineResult<RuntimeSignal> {
    match &node.kind {
        CompiledNodeKind::WaitUntil { deadline_slot } => handle_wait_until(run, *deadline_slot),
        CompiledNodeKind::WaitEvent {
            event,
            timeout_slot,
        } => handle_wait_event(run, *event, *timeout_slot),
        CompiledNodeKind::Ask {
            prompt,
            timeout_slot,
        } => handle_ask(run, *prompt, *timeout_slot),
        CompiledNodeKind::AskResume { answer } => {
            handle_ask_resume(run, *answer, node.output, node.next, node.id)
        }
        _ => Err(family_invariant()),
    }
}

#[allow(clippy::too_many_arguments)]
fn dispatch_action(
    run: &mut RunFrame,
    node: &CompiledNode,
    contracts: &[ActionContract],
    retry_policy: RetryPolicy,
    granted: &CapabilitySet,
) -> RuntimeEngineResult<RuntimeSignal> {
    match &node.kind {
        CompiledNodeKind::Do { action, input } => handle_do(
            run,
            *action,
            *input,
            contracts,
            granted,
            retry_policy,
            node.id,
        ),
        CompiledNodeKind::RetryCheck {
            policy_slot,
            body,
            exhausted,

        .map_err(RuntimeEngineError::Core)
        .map(runtime_from_core)
}

// ── Do handler ───────────────────────────────────────────────────
pub(super) fn handle_do(
    run: &mut RunFrame,
    action: ActionId,
    input: SlotIdx,
    contracts: &[ActionContract],
    granted: &CapabilitySet,
    retry_policy: RetryPolicy,
    node_id: StepIdx,
) -> RuntimeEngineResult<RuntimeSignal> {
    let seq = SeqNo::new(run.executed());
    if contracts.is_empty() {
        execute_do_without_contract(run, node_id, action, input, seq, granted, retry_policy)
    } else {
        execute_do(
            run,
            node_id,
            action,
            input,
            seq,
            resolve_contract(action, contracts)?,
            contracts,
            granted,
            retry_policy,
        )
    }
}

// ── ErrorHandler handler ─────────────────────────────────────────
pub(super) fn handle_error_handler(
    run: &mut RunFrame,
    handler_body: StepIdx,
) -> RuntimeEngineResult<RuntimeSignal> {
    run.set_pc(handler_body).map_err(RuntimeEngineError::Core)?;
    run.increment_executed().map_err(RuntimeEngineError::Core)?;
    Ok(RuntimeSignal::Continue)
}

